.main {max-width: 1280px; margin: 0 auto; padding: var(--g-spacing-8) var(--g-spacing-8) var(--g-spacing-5);}
.breadcrumb {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-hint); font-size: 12px; margin-bottom: var(--g-spacing-6);}
.breadcrumb span:last-child {color: var(--g-color-text-secondary);}
.page-heading {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-7);}
.page-heading > div {min-width: 0;}
.page-heading > button {flex-shrink: 0;}
.title-line {display: flex; align-items: center; gap: var(--g-spacing-4); flex-wrap: wrap;}
