.live-status > span,.status-dot {display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--g-color-text-positive);}
.subtitle {margin: var(--g-spacing-2) 0 0;}
.filters {display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-5);}
.period-controls {display: flex; align-items: center; gap: var(--g-spacing-5); min-width: 0;}
.date-range {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 12px; color: var(--g-color-text-secondary); white-space: nowrap;}
.metrics {display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: var(--g-spacing-4); margin-bottom: var(--g-spacing-6);}
.metric-card {height: 142px; display: block; min-width: 0; text-align: left; background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); --g-button-padding: 20px; --g-button-background-color-hover: var(--g-color-base-generic-ultralight); --g-button-border-radius: var(--g-border-radius-l); transition: border-color .2s, background .2s;}
.metric-card-selected {background: var(--g-color-base-utility-light); border-color: var(--g-color-text-utility); --g-button-background-color-hover: var(--g-color-base-utility-light-hover);}
.metric-top {display: flex; align-items: center; justify-content: space-between; color: var(--g-color-text-secondary); font-size: 13px; line-height: 20px; margin-bottom: var(--g-spacing-3);}
.metric-card-selected .metric-top {color: var(--g-color-text-utility);}
.metric-value {display: block; line-height: 38px; font-weight: 600; letter-spacing: -.7px; margin-bottom: var(--g-spacing-3);}
.metric-bottom {display: flex; align-items: center; gap: var(--g-spacing-2); font-size: 10px; line-height: 16px; color: var(--g-color-text-secondary); white-space: nowrap;}
.growth {display: inline-flex; align-items: center; gap: 2px; font-size: 11px; color: var(--g-color-text-positive); font-weight: 500;}
.chart-panel {background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); overflow: hidden;}
.chart-heading {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding: var(--g-spacing-6) var(--g-spacing-6) 0;}
.chart-title {display: flex; align-items: center; gap: var(--g-spacing-2);}
.chart-title h2 {margin: 0; font-weight: 600; letter-spacing: -.2px;}
.chart-description {margin: var(--g-spacing-1) 0 0;}
.chart-toolbar {display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); padding: var(--g-spacing-6) var(--g-spacing-6) 0;}
.legend {display: flex; align-items: center; flex-wrap: wrap; gap: var(--g-spacing-5); font-size: 12px;}
.legend-item {display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary);}
.legend-line {width: 20px; height: 0; border-top: 3px solid var(--g-color-text-utility); border-radius: var(--g-border-radius-xs);}
.legend-line.previous {border-top: 2px dashed var(--g-color-text-hint);}
.chart-wrap {height: 328px; padding: 0 var(--g-spacing-5) 0 var(--g-spacing-3); margin-top: var(--g-spacing-3); --gcharts-axis-tick-color: var(--g-color-line-generic);}
.chart-footer {display: flex; justify-content: space-between; align-items: center; padding: var(--g-spacing-4) var(--g-spacing-6); font-size: 11px; color: var(--g-color-text-hint); border-top: 1px solid var(--g-color-line-generic);}
.chart-footer > span:first-child {display: flex; align-items: center; gap: var(--g-spacing-2);}
.status-dot {width: 5px; height: 5px; background: var(--g-color-text-hint);}
.help-note {margin: var(--g-spacing-4) var(--g-spacing-6) 0; padding: var(--g-spacing-3); background: var(--g-color-base-info-light); color: var(--g-color-text-info); border-radius: var(--g-border-radius-m); line-height: 1.6;}
.details {display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); padding: var(--g-spacing-6) 0; margin: var(--g-spacing-5) 0; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); background: var(--g-color-base-background);}
.detail-item {display: flex; align-items: center; gap: var(--g-spacing-4); padding: 0 var(--g-spacing-6); min-width: 0;}
.detail-item + .detail-item {border-left: 1px solid var(--g-color-line-generic);}
.detail-icon {display: grid; place-items: center; flex-shrink: 0; width: 40px; height: 40px; background: var(--g-color-base-generic); color: var(--g-color-text-secondary); border-radius: var(--g-border-radius-m);}
.positive-icon {background: var(--g-color-base-positive-light); color: var(--g-color-text-positive);}
.detail-item p {margin: 0;}
.detail-item p + p {margin-top: var(--g-spacing-2);}
.detail-unit {font-size: 11px; font-weight: 400; color: var(--g-color-text-hint); margin-left: var(--g-spacing-2); white-space: nowrap;}
.positive {color: var(--g-color-text-positive);}
.insight {display: flex; align-items: center; gap: var(--g-spacing-4); padding: var(--g-spacing-5) var(--g-spacing-6); background: var(--g-color-base-utility-light); border: 1px solid var(--g-color-line-utility); border-radius: var(--g-border-radius-l);}
.insight-icon {display: grid; place-items: center; width: 40px; height: 40px; border: 1px solid var(--g-color-line-utility); border-radius: var(--g-border-radius-m); color: var(--g-color-text-utility); flex-shrink: 0;}
.insight p {margin: 0;}
.insight p + p {margin-top: var(--g-spacing-1);}
.insight-spark {color: var(--g-color-text-utility); font-size: 32px; margin-left: auto; padding-left: var(--g-spacing-4);}
.page-footer {display: flex; align-items: center; justify-content: space-between; color: var(--g-color-text-hint); font-size: 11px; gap: var(--g-spacing-4); padding-top: var(--g-spacing-6);}
.page-footer > span:last-child {display: flex; align-items: center; gap: var(--g-spacing-2);}
@media (min-width: 1450px) {.main {padding-top: var(--g-spacing-9);}}
@media (max-width: 1050px) {
  .live-status,.theme-label {display: none;}
  .metric-bottom {gap: var(--g-spacing-1); font-size: 9px;}
  .metric-card {--g-button-padding: 16px;}
  .detail-unit {display: block; margin: var(--g-spacing-1) 0 0;}
}
@media (max-width: 760px) {
  .topbar {height: 64px;}
  .topbar-inner {padding: 0 var(--g-spacing-4); gap: var(--g-spacing-3);}
  .workspace-label {display: none;}
  .main {padding: var(--g-spacing-5) var(--g-spacing-4);}
  .breadcrumb {margin-bottom: var(--g-spacing-5);}
  .title-line h1 {font-size: var(--g-text-header-1-font-size); line-height: var(--g-text-header-1-line-height); letter-spacing: -.5px;}
  .page-heading {align-items: flex-start; margin-bottom: var(--g-spacing-5);}
  .subtitle {max-width: 260px; font-size: 12px;}
  .filters {align-items: flex-start;}
  .period-controls {flex-direction: column; align-items: flex-start; gap: var(--g-spacing-3);}
  .date-range {font-size: 11px;}
  .metrics {grid-template-columns: repeat(2,minmax(0,1fr)); gap: var(--g-spacing-3);}
  .metric-card {height: 138px;}
  .metric-bottom {font-size: 10px;}
  .chart-heading {padding: var(--g-spacing-4) var(--g-spacing-4) 0;}
  .chart-title {gap: var(--g-spacing-1);}
  .chart-title h2 {font-size: var(--g-text-subheader-3-font-size); line-height: var(--g-text-subheader-3-line-height);}
  .chart-description {font-size: 11px;}
  .chart-toolbar {flex-direction: column; align-items: flex-start; padding: var(--g-spacing-5) var(--g-spacing-4) 0; gap: var(--g-spacing-4);}
  .legend {gap: var(--g-spacing-4); font-size: 11px;}
  .chart-wrap {height: 290px; padding-right: var(--g-spacing-2); padding-left: var(--g-spacing-1);}
  .chart-footer {padding: var(--g-spacing-3) var(--g-spacing-4); font-size: 10px;}
  .details {grid-template-columns: 1fr; padding: 0;}
  .detail-item {padding: var(--g-spacing-4);}
  .detail-item + .detail-item {border-left: 0; border-top: 1px solid var(--g-color-line-generic);}
  .detail-unit {display: inline; margin-left: var(--g-spacing-2);}
  .detail-item p + p {margin-top: var(--g-spacing-1);}
  .insight {padding: var(--g-spacing-4); gap: var(--g-spacing-3); align-items: flex-start;}
  .insight-spark {display: none;}
  .insight p {line-height: 1.55;}
  .page-footer {align-items: flex-start; flex-direction: column; gap: var(--g-spacing-2);}
}
@media (prefers-reduced-motion: reduce) {* {transition: none "'!important;}}
EOF
'

